function cohortBuilder(){const criteria=[['纳入','年龄 ≥ 18 岁','人口学/出生日期','通过','green'],['纳入','2024-01-01 至 2026-06-30 有高血压诊断','诊断/ICD-10 I10','通过','green'],['纳入','观察窗内至少 2 次门诊血压','体征/收缩压/舒张压','通过','green'],['排除','妊娠相关高血压','诊断 O10–O16','通过','green'],['排除','eGFR < 30 ml/min/1.73m²','LIS/肾功能','2.1% 缺失','amber']];return pageHead('科研队列构建器','RES-2026-014 · 队列定义 v6 · 数据截止 2026-06-30','<button class="btn">导入口径</button><button class="btn primary">运行去标识计数</button>')+`<div class="cohort-layout"><aside class="card cohort-criteria"><div class="card-head">队列结构</div>${[['研究人群','高血压门诊患者'],['索引日期','首次满足条件日期'],['基线窗','索引前 365 天'],['观察窗','索引后 180 天'],['去重','每患者一个索引事件']].map(x=>`<div class="folder-row">${x[0]}<span>${x[1]}</span></div>`).join('')}<div class="notice ai"><div class="notice-title">✦ 自然语言助手</div>“筛选成年高血压患者，排除妊娠和重度肾功能不全”已翻译为结构化条件，必须人工确认后运行。</div></aside><section class="card"><div class="card-head">纳入与排除条件 <span class="status amber">1 数据质量提示</span></div><table class="table"><thead><tr><th>类型</th><th>条件</th><th>来源字段</th><th>预检</th></tr></thead><tbody>${criteria.map(x=>`<tr><td><span class="status ${x[0]==='纳入'?'blue':'red'}">${x[0]}</span></td><td><b>${x[1]}</b></td><td>${x[2]}</td><td><span class="status ${x[4]}">${x[3]}</span></td></tr>`).join('')}</tbody></table><div class="card-body"><div class="cohort-funnel">${[['全院患者','2,184,320'],['诊断匹配','86,421'],['年龄/日期','72,804'],['血压次数','14,211'],['排除条件后','12,486']].map((x,i)=>`<div style="width:${100-i*14}%"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></div></section><aside class="card"><div class="card-head">隐私与可复算性</div><div class="card-body">${[['当前结果','仅聚合计数'],['小样本规则','分层 <10 抑制'],['术语版本','ICD-10 2026.1'],['数据快照','CDR-20260630-v4'],['执行引擎','cohort-engine v2.8'],['缺失规则','不默认等于阴性'],['复算标识','COHORT-v6-RUN-19']].map(x=>`<div class="folder-row">${x[0]}<span>${x[1]}</span></div>`).join('')}<button class="btn" style="width:100%;margin-top:12px" data-jump="research-stats">查看统计结果</button></div></aside></div>`}

