const baseRender=render;
render=function(){if(!renderers[current])current='clinical';let content=renderers[current]();if(outpatientRoutes.includes(current))content=domainNav('outpatient',current)+content;if(emergencyRoutes.includes(current))content=domainNav('emergency',current)+content;if(inpatientRoutes.includes(current)||current==='ward')content=domainNav('inpatient',current)+content;if(recordRoutes.includes(current))content=recordNav(current)+content;if(archiveRoutes.includes(current))content=archiveNav(current)+content;if(integrationRoutes.includes(current))content=integrationNav(current)+content;if(researchRoutes.includes(current))content=researchNav(current)+content;if(adminRoutes.includes(current))content=adminShell(current,content);document.getElementById('app').innerHTML=shell(content);document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{current=b.dataset.page;location.hash=current;render()});document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{current=b.dataset.jump;location.hash=current;render()});};
render();
